import assert from "node:assert/strict";
import pg from "pg";
const root="http://dealer.qa.test:8080",other="http://other.qa.test:8080",admin={authorization:"Basic ZGVhbGVyOnFh"},otherAdmin=admin;
const clients="/api/clients",rep="/api/reputation",vin="1A000000000000070",vin2="1A000000000000071";
const req=(p,input,method=input?"POST":"GET",auth=admin,base=root)=>fetch(base+p,{method,headers:{...auth,origin:base,"content-type":"application/json"},body:input?JSON.stringify(input):undefined});
async function check(p,status=200){const r=await p,data=await r.json();assert.equal(r.status,status,JSON.stringify(data));return data;}
const lookup=(search)=>check(req(clients+"?search="+encodeURIComponent(search)));
const person={name:"Ben Pipeline",email:"ben.pipeline@example.test",phone:"740.555.0177"},bookPath="/api/test-drives?vin="+vin;
// Earlier fixtures provision a partial second physical database. Add the standard booking table.
const separate=new pg.Client({connectionString:"postgres://showroom@database/client_10000000000000000000000000000002"});await separate.connect();
await separate.query("CREATE TABLE IF NOT EXISTS appointments(key text PRIMARY KEY,confirmation text UNIQUE NOT NULL,body jsonb NOT NULL,notes jsonb DEFAULT '{}')");await separate.end();
const slot=(await check(req(bookPath))).slots[0],web={...person,message:"Trade to discuss",slot,requestId:crypto.randomUUID()};
const receipt=await check(req(bookPath,web,"POST",{}),201);
assert.equal((await check(req(bookPath,web,"POST",{}))).confirmation,receipt.confirmation);
const id=(await lookup("Ben Pipeline")).items[0].id,profile=()=>check(req(clients+"?id="+id));
let d=await profile();assert.equal(d.visits.length,1);assert.equal(d.deals[0].stage,"scheduled");
assert.equal((await check(req(clients+"?visit="+receipt.confirmation))).client.id,id);
assert.equal((await req(clients,null,"GET",{})).status,403);assert.equal((await req(clients+"?id="+id,null,"GET",otherAdmin,other)).status,404);
await check(req("/api/inquiries",{carId:vin,name:person.name,email:person.email,phone:"(740) 555-0177",message:"Does the trade qualify?"},"POST",{}),201);
assert.equal((await profile()).inquiries.length,1);assert.equal((await lookup(person.email)).items.length,1);
const update=(stage,revision,cents,note="",extra={})=>req(clients,{id,vin,stage,revision,cents,note,...extra},"PUT");
await check(update("followup",0,null,"Discuss trade"));
await check(update("presented",1,1567099));
await check(update("signed",2,null),422);
const race=await Promise.all([update("signed",2,1567099),update("signed",2,1667099)]);assert.deepEqual(race.map(x=>x.status).sort(),[200,409]);
d=await profile();const deal=d.deals.find(v=>v.vin===vin);assert.equal(deal.stage,"signed");assert.ok([1567099,1667099].includes(Number(deal.cents)));assert.equal(d.changes.length,3);
const manual={action:"intake",request:crypto.randomUUID(),source:"Phone call",name:"Manual Appointment",phone:"7405550182",email:"",vin:vin2,note:"Interested in the sedan"};
const added=await check(req(clients,manual));assert.equal((await check(req(clients,manual)).then(x=>x.id)),added.id);
const manualBooking={id:added.id,action:"book",request:crypto.randomUUID(),vin:vin2,slot:(await check(req("/api/test-drives?vin="+vin2))).slots[0],note:"Called the desk"};
const booked=await check(req(clients,manualBooking));await check(req(clients,manualBooking));await check(req(clients,{...manualBooking,request:crypto.randomUUID()}),409);
let m=await check(req(clients+"?id="+added.id));assert.equal(m.visits.length,1);assert.equal(m.inquiries.length,0);assert.equal(m.intakes.length,1);assert.equal(m.deals[0].stage,"scheduled");assert.equal(m.client.email,null);
const schedules=await check(req("/api/test-drives/desk"));assert.ok(schedules.appointments.some(a=>a.confirmation===booked.confirmation));
const db=new pg.Client({connectionString:"postgres://showroom@database/showroom"});await db.connect();
try{await db.query("SET search_path TO client_10000000000000000000000000000001");
  await db.query("UPDATE appointments SET body=jsonb_set(body,'{slot}',to_jsonb((now()-interval '2 hours')::text)) WHERE confirmation=$1",[booked.confirmation]);
}finally{await db.end();}
const visitChange=(action,revision,note)=>check(req("/api/test-drives/desk",{confirmation:booked.confirmation,action,revision,note},"PUT"));
await visitChange("attended",0,"");m=await check(req(clients+"?id="+added.id));assert.equal(m.deals[0].stage,"attended");
assert.ok((await check(req(rep))).items.some(x=>x.id===added.id));
await visitChange("missed",1,"Corrected attendance");assert.ok(!(await check(req(rep))).items.some(x=>x.id===added.id));
await visitChange("attended",2,"Verified attendance");
await check(req(clients,{...manual,request:crypto.randomUUID(),name:person.name,email:person.email,phone:"7405550177",source:"Walk-in"}));
assert.equal((await profile()).deals.length,2);assert.equal((await profile()).deals.find(v=>v.vin===vin2).cents,null);
const settings=await check(req(rep));assert.equal(settings.items.filter(x=>x.id===id).length,1);assert.equal(settings.items.find(x=>x.id===id).experience,"Purchased");
assert.equal((await req(rep,null,"GET",{})).status,403);
await check(req(rep,{revision:settings.revision,link:"https://example.test/review"},"PUT"),422);
await check(req(rep,{revision:settings.revision,link:"https://g.page/r/example/review"},"PUT"));await check(req(rep,{revision:settings.revision,link:""},"PUT"),409);
assert.equal((await check(req(rep,null,"GET",otherAdmin,other))).link,"");
const login=await req("/api/dealer-auth/signin",{email:"terry@example.test",password:"only-for-local-fixture-169"},"POST",{});
const staff={cookie:login.headers.get("set-cookie").split(";")[0]};assert.equal((await req(rep,{revision:1,link:""},"PUT",staff)).status,403);
await check(req("/api/conversations",{id,owner:"account:review.writer@example.test",stage:"Working",revision:0},"PUT"));
assert.equal((await req(clients,{id,vin,stage:"signed",revision:3,cents:12300,note:""},"PUT",staff)).status,403);
assert.equal((await req(clients,{...manualBooking,id,request:crypto.randomUUID()},"POST",staff)).status,403);
assert.ok((await lookup("Past visitor")).items.length);
console.log("Passed sales clients, booking and inquiry identity, historical visits, per-vehicle contract values, phone intake, attendance corrections, reputation eligibility, permissions and rooftop isolation.");
